-- Semantic world-link data generated by the offline ROM importer.
package.path = "decompilation/gameplay/scripts/?.lua;" ..
    "decompilation/gameplay/scripts/?/init.lua;" .. package.path

local W = require("world_links")
local E = require("enums")
local D = W.data()

local pass, total = 0, 0
local function check(cond, label)
    total = total + 1
    if cond then pass = pass + 1 else print("FAIL " .. label) end
end

-- Each imported link is already expressed as bounds and a semantic transition.
local directions = { north = true, east = true, south = true, west = true }
local links, routed = 0, 0
for scene_id = 0, 55 do
    local scene = D.scenes[scene_id]
    check(scene ~= nil, "scene " .. scene_id .. " present")
    check(scene.event_destinations == nil,
          "ROM selector tables stay out of Lua data " .. scene_id)
    for _, link in ipairs(W.links_in_scene(scene_id)) do
        links = links + 1
        local bounds = link.bounds
        check(directions[link.return_side] == true, "named return side")
        check(bounds.left <= bounds.right and bounds.top <= bounds.bottom,
              "ordered world bounds")
        check(link.transition ~= nil and
              W.transition_at(scene_id, bounds.left, bounds.top) ~= nil,
              "doorway resolves directly to a gameplay transition")
        if link.transition.kind == "scene_change" then
            routed = routed + 1
            check(W.scene_mode(link.transition.destination_scene_id) ~= nil and
                  D.scenes[link.transition.destination_scene_id] ~= nil,
                  "destination has a scene profile")
        else
            check(link.transition.kind == "same_map_service" or
                  link.transition.kind == "contextual_transition" or
                  link.transition.kind == "unresolved_destination",
                  "non-scene doorway transition has a named kind")
        end
    end
end
check(links == 892, "892 imported doorway links, got " .. links)
check(routed > 0, "some doors route")
check(W.transition_at(2, 7424, 2304).destination_scene_id == 13,
      "Redmond doorway routes to the Jump House")
check(W.transition_at(0, 8448, 1792).destination_scene_id == 10,
      "Downtown doorway routes to the destination scene")
-- ROM 0x167AE treats 0x0D as a field-scene result; the importer exposes that
-- field mode as `street` (scene profile 0x1B3C06), not as a resource scene.
check(W.scene_mode(0x0D) == "street" and
      W.scene_mode(0x2D) == "cave" and W.scene_mode(64) == nil,
      "scene profiles carry semantic location modes")

-- Door return formations are keyed by compass side and use map positions.
check(D.return_offsets.south[1].y == 0x140 and
      D.return_offsets.north[1].y == -0x140, "north/south formations")
check(D.return_offsets.east[1].x == 0x1E0 and
      D.return_offsets.west[1].x == -0x1E0, "east/west formations")

-- Sweep every outdoor link that enters a building or same-map service. ROM
-- 0xBC36 selects one of the four 0xBD34 banks and copies its three pairs to
-- FFDF44..4E; expected values below are decoded from that ROM table, not from
-- the runtime Lua data. 0x09B8 supplies heading $8000 on service return.
local ROM_RETURN_BANKS = {
    north = { { 0, -0x140 }, { -0x140, -0x140 }, { 0x140, -0x140 } },
    east = { { 0x1E0, 0 }, { 0x140, 0x140 }, { 0x140, -0x140 } },
    south = { { 0, 0x140 }, { 0x140, 0x140 }, { -0x140, 0x140 } },
    west = { { -0x1E0, 0 }, { -0x100, 0x140 }, { -0x100, -0x100 } },
}
local building_service_exits = W.building_service_exit_cases()
for _, exit_case in ipairs(building_service_exits) do
    local expected_bank = ROM_RETURN_BANKS[exit_case.return_side]
    check(expected_bank ~= nil,
          exit_case.exit_id .. " has a ROM return bank")
    local point = W.door_contact{
        outdoor_field = true,
        return_side = exit_case.return_side,
        lead = exit_case.contact,
        camera = { x = 0, y = 0 },
    }
    check(point.saved,
          exit_case.exit_id .. " saves the source return point")
    local entry_bearing = exit_case.return_side == "south" and 0 or
        exit_case.return_side == "north" and 180 or
        exit_case.return_side == "east" and 270 or 90
    local policy = W.building_service_exit_policy{
        exit_id = exit_case.exit_id,
    }
    local returned = W.building_service_exit_return{
        point = point,
        entry_bearing_degrees = entry_bearing,
        return_anchor = policy.return_anchor,
        return_facing = policy.return_facing,
        return_music_policy = policy.return_music_policy,
    }
    for runner = 1, 3 do
        local expected = expected_bank[runner]
        local actual = returned.party[runner]
        check(actual.x == exit_case.contact.x + expected[1] and
              actual.y == exit_case.contact.y + expected[2],
              exit_case.exit_id .. " runner " .. runner ..
                  " matches the ROM bank at 0xBD34")
    end
    local returned_bearing = returned.bearing_degrees
    check(returned_bearing == 180,
          exit_case.exit_id .. " returns at outward heading $8000")
    check(returned.return_anchor ==
              E.FieldLocationReturnAnchor.COLLISION_PROBE_LEAD and
          returned.return_facing ==
              E.FieldLocationReturnFacing.FACE_AWAY_FROM_ENTRY and
          returned.return_music_policy ==
              E.FieldLocationMusicReturnPolicy.RESUME_SCENE_PROFILE,
          exit_case.exit_id .. " gets the shared typed exit policy")
    check(policy.return_music_policy ==
              E.FieldLocationMusicReturnPolicy.RESUME_SCENE_PROFILE,
          exit_case.exit_id .. " requests source profile music on return")
    print(string.format(
        "field_exit_return_sweep id=%s scene=%d link=%d side=%s " ..
        "contact=%d,%d return=%d,%d heading=0x%04X",
        exit_case.exit_id, exit_case.scene_id, exit_case.link_index,
        exit_case.return_side, exit_case.contact.x, exit_case.contact.y,
        returned.party[1].x, returned.party[1].y,
        math.floor(returned_bearing * 65536 / 360)))
end
check(#building_service_exits == 30,
      "30 outdoor building/service links receive a measured return, got " ..
          #building_service_exits)
local exit_exceptions = W.building_service_exit_exceptions()
for _, exception in ipairs(exit_exceptions) do
    print(string.format("field_exit_return_exception id=%s rom=%s anchor=%s " ..
        "facing=%s", exception.exit_id, exception.rom_address,
        exception.return_anchor, exception.return_facing))
end
local exceptions_by_id = {}
for _, exception in ipairs(exit_exceptions) do
    exceptions_by_id[exception.exit_id] = exception
end
local medicine_lodge_exception =
    exceptions_by_id["council_medicine_lodge.rom_event_06"]
check(medicine_lodge_exception ~= nil and
      medicine_lodge_exception.rom_address == "0x15BDB0" and
      medicine_lodge_exception.return_anchor ==
          E.FieldLocationReturnAnchor.NONE and
      medicine_lodge_exception.return_facing ==
          E.FieldLocationReturnFacing.PRESERVE_ENTRY and
      medicine_lodge_exception.return_music_policy ==
          E.FieldLocationMusicReturnPolicy.NONE,
      "Scene 4/event 6 stays outside the doorway return policy [0x15BDB0]")
-- [C] Scene-18 record 9 at 0x1D5E38 dispatches Julius's same-map dialogue;
-- closing that route preserves its live field position and field music.
local julius_exception =
    exceptions_by_id["julius_strouther_booth.rom_event_30"]
check(julius_exception ~= nil and
      julius_exception.rom_address == "0x1D5E38" and
      julius_exception.return_anchor == E.FieldLocationReturnAnchor.NONE and
      julius_exception.return_facing ==
          E.FieldLocationReturnFacing.PRESERVE_ENTRY and
      julius_exception.return_music_policy ==
          E.FieldLocationMusicReturnPolicy.NONE,
      "Julius's same-map dialogue keeps its live field position [0x1D5E38]")
-- [C] Scene-19 record 12/event 30 at 0x1D5F50 reaches the default
-- same-map prompt 0x20C78; it is not a building-door return.
local jackals_old_man_exception =
    exceptions_by_id["jackals_lantern_old_man_contact.rom_event_30"]
check(#exit_exceptions == 3 and jackals_old_man_exception ~= nil and
      jackals_old_man_exception.rom_address == "0x1D5F50" and
      jackals_old_man_exception.return_anchor ==
          E.FieldLocationReturnAnchor.NONE and
      jackals_old_man_exception.return_facing ==
          E.FieldLocationReturnFacing.PRESERVE_ENTRY and
      jackals_old_man_exception.return_music_policy ==
          E.FieldLocationMusicReturnPolicy.NONE,
      "Jackal's Lantern old-man dialogue preserves the live field state [0x1D5F50]")

local function contact(x, y, side)
    return W.door_contact{
        outdoor_field = true,
        lead = { x = x, y = y },
        camera = { x = 1, y = 2 },
        return_side = side,
    }
end
local cases = {
    { "motel run5", 15584, 10890,
      { { 15584, 11210 }, { 15904, 11210 }, { 15264, 11210 } } },
    { "Little Chiba", 28424, 9350,
      { { 28424, 9670 }, { 28744, 9670 }, { 28104, 9670 } } },
    { "Jump House", 7344, 2680,
      { { 7344, 3000 }, { 7664, 3000 }, { 7024, 3000 } } },
}
for _, c in ipairs(cases) do
    local result = contact(c[2], c[3], "south")
    check(result.saved, c[1] .. " return point saved")
    for runner = 1, 3 do
        check(result.party[runner].x == c[4][runner][1] and
              result.party[runner].y == c[4][runner][2],
              c[1] .. " party member " .. runner)
    end
    check(result.camera.x == 1 and result.camera.y == 2,
          c[1] .. " camera position")
end
local interior = W.door_contact{
    outdoor_field = false,
    lead = { x = 1, y = 1 },
    camera = { x = 0, y = 0 },
    return_side = "north",
}
check(not interior.saved and interior.party == nil,
      "interior contact keeps the previous return point")
check(not pcall(W.door_contact, {
    outdoor_field = true, lead = { x = 0, y = 0 },
    camera = { x = 0, y = 0 }, return_side = "diagonal",
}), "unknown return side rejected")

-- [C] ROM 0xBC36/0xBD34 restores the saved probe triplet; 0x09B8..0x09E0
-- writes $8000 for the nonzero exit path. Building/service links share that
-- one typed return policy.
local point = contact(15584, 10890, "south")
local generic_exit = W.building_service_exit_return{
    point = point,
    entry_bearing_degrees = 0,
}
check(generic_exit.party == point.party and
      generic_exit.camera == point.camera and
      generic_exit.bearing_degrees == 180 and
      generic_exit.return_anchor ==
          E.FieldLocationReturnAnchor.COLLISION_PROBE_LEAD and
      generic_exit.return_facing ==
          E.FieldLocationReturnFacing.FACE_AWAY_FROM_ENTRY and
      generic_exit.return_music_policy ==
          E.FieldLocationMusicReturnPolicy.RESUME_SCENE_PROFILE,
      "generic building/service exit restores the saved point and faces out")
for _, bearing in ipairs({ 0, 90, 180, 270, 45, 315 }) do
    check(W.exit_bearing({
        facing_policy = E.FieldLocationReturnFacing.FACE_AWAY_FROM_ENTRY,
        entry_bearing_degrees = bearing,
    }).bearing_degrees == (bearing + 180) % 360,
       "face away from " .. bearing .. " degrees")
    check(W.exit_bearing({
        facing_policy = E.FieldLocationReturnFacing.PRESERVE_ENTRY,
        entry_bearing_degrees = bearing,
    }).bearing_degrees == bearing,
       "preserve " .. bearing .. " degrees")
end
check(not pcall(W.exit_bearing, {
    facing_policy = "unknown", entry_bearing_degrees = 0,
}), "unknown facing policy rejected")

-- Service transitions are attached to the actual doorway geometry.
check(W.service_at(2, 28416, 8960).kind == "hospital",
      "Little Chiba hospital")
check(W.service_at(2, 15616, 10496).kind == "hotel",
      "Stoker motel hotel")
check(W.service_at(2, 19712, 8960).kind == "shop",
      "Ares shop")
check(W.service_at(2, 7424, 2304) == nil,
      "Jump House is not a same-map service")

-- The importer resolves cave graph indices into named exits and positions.
check(W.entry_room(6) == 0 and W.entry_room(9) == 3 and
      W.entry_room(2) == nil, "optional entry rooms")
check(D.cave_rooms[W.entry_room(9)].scene == 9 and
      D.cave_rooms[W.entry_room(6)].scene == 6,
      "entry rooms match their destination scenes")
local function cave_exit(room, direction)
    return W.cave_exit({ room = room, direction = direction })
end
local first_exit = cave_exit(0, "north")
check(first_exit.room == 5 and first_exit.scene == 0x2D and
      first_exit.arrival.x == 0x5E00 and first_exit.arrival.y == 0x2280,
      "room 0 north resolves to room 5 and its arrival position")
check(cave_exit(0, "west").room == 0 and
      cave_exit(25, "north") == nil,
      "named exits preserve self-links and reject missing rooms")
local edges = {
    {0,5},{0,6},{0,7},{1,7},{1,11},{2,4},{2,5},{2,9},{2,10},{3,13},
    {3,15},{3,16},{4,5},{7,8},{10,11},{11,12},{12,13},{14,15},{16,17},
    {16,18},{18,21},{19,20},{20,21},{21,23},{22,23},
}
local function linked(from, to)
    for _, direction in ipairs({ "north", "east", "south", "west" }) do
        local exit = cave_exit(from, direction)
        if exit and exit.room == to then return true end
    end
    return false
end
for _, edge in ipairs(edges) do
    check(linked(edge[1], edge[2]) and linked(edge[2], edge[1]),
          "cave connection " .. edge[1] .. "-" .. edge[2])
end
local seen, queue = { [0] = true }, { 0 }
while #queue > 0 do
    local room = table.remove(queue)
    for _, edge in ipairs(edges) do
        for index = 1, 2 do
            local from, to = edge[index], edge[3 - index]
            if from == room and not seen[to] then
                seen[to] = true
                queue[#queue + 1] = to
            end
        end
    end
end
local reached = 0
for _ in pairs(seen) do reached = reached + 1 end
check(reached == 24, "all 24 cave rooms are connected")

print(string.format("world_links: %d/%d", pass, total))
os.exit(pass == total and 0 or 1)
